local KTool = CS.Engine.Lib.KTool

local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"

--- from: Assets/BundleResources/Prefabs/OverseaChat/OverseaChatDialog.prefab
---@class OverseaChatFriendCell
---@field Env                            OverseaChatFriendCell
---@field controller                        Engine.Modules.LuaBehaviour
---@field CommonRedPoint                    UnityEngine.RectTransform
---@field BtnChat                        UnityEngine.RectTransform
---@field TextNumber                        TMPro.TextMeshProUGUI
---@field TextName                        UnityEngine.UI.Text
---@field OffLine                        UnityEngine.RectTransform
---@field OnLine                            UnityEngine.RectTransform
---@field CommonPlayerHeadNode            UnityEngine.RectTransform
local OverseaChatFriendCell = Class('OverseaChatFriendCell')

function OverseaChatFriendCell:__init()
    self.data = nil
    self.cb = nil
end

function OverseaChatFriendCell:__delete()
    self.data = nil
    self.cb = nil
end

function OverseaChatFriendCell:Awake()
    SetButtonAction(self.BtnChat, function()
        if self.cb then
            self.cb(self.data)
            local social = AppService:GetInstance():GetSocialLine()
            ---修改数据为已读
            social:ReadUnreadMessage(checkNumber(self.data.friendId))
            GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OverseaChat)
        end
    end)
end

function OverseaChatFriendCell:GetOfflineTimeDesc(seconds)
    seconds = checkInt(seconds)
    local desc
    if seconds < 60 then
        desc = localize("_num_秒前", {_num_ = seconds})
    elseif seconds < 3600 then
        desc = localize("_num_分钟前", {_num_ = math.floor(seconds / 60)})
    elseif seconds < 86400 then
        desc = localize("_num_小时前", {_num_ = math.floor(seconds / 3600)})
    elseif seconds < 2592000 then
        desc = localize("_num_天前", {_num_ = math.floor(seconds / 86400)})
    elseif seconds < 7776000 then
        desc = localize("_num_月前", {_num_ = math.floor(seconds / 2592000)})
    elseif seconds >= 7776000 then
        desc = localize("3月以上")
    end
    return desc
end

function OverseaChatFriendCell:FreshUI(data, cb)
    self.data = data
    if checkNumber(data.friendId) > 0 then
        self.cb = cb
        CfUtils.FillText(self.TextName, tostring(data.name))
        CfUtils.FillText(self.TextNumber, tostring(data.level))
        ---@type CommonPlayerHeadNode
        local env = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
        if env then
            env:FreshAvatarFrame(data.avatar, data.avatarFrame)
            env:SetCallBack(function()
                GameUtils.ShowPlayerInfo(
                        data.playerId or data.friendId,
                        nil,
                        nil,
                        {panelMode = true, chatEnter = true}
                )
            end)
        end
        KTool.SetActive(self.OnLine.gameObject, checkNumber(data.isOnline) == 1)
        KTool.SetActive(self.OffLine.gameObject, checkNumber(data.isOnline) ~= 1)
        if checkNumber(data.isOnline) ~= 1 then
            ---离线
            CfUtils.FillText(self.OffLine.transform:Find("TextDesc"), self:GetOfflineTimeDesc(checkNumber(data.lastExitTime)))
        end
        local social = AppService:GetInstance():GetSocialLine()
        local isHave = social:IsHaveUnreadMsgByPlayerId(checkNumber(data.friendId))
        KTool.SetActive(self.CommonRedPoint.gameObject, checkBool(isHave))
    else
        KTool.SetActive(self.CommonRedPoint.gameObject, false)
    end

end

function OverseaChatFriendCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return OverseaChatFriendCell